inputs = ['awgz', 'kzhfg', 'jzaiw', 'zgwdu', 'jj']
outputs = ['awgvz', 'kvzhfg', 'jvzaiw', 'bwdu', 'jj']

# Analyze each changed pair
changed_pairs = [(0, 'awgz', 'awgvz'), (1, 'kzhfg', 'kvzhfg'), (2, 'jzaiw', 'jvzaiw'), (3, 'zgwdu', 'bwdu')]

for idx, inp, outp in changed_pairs:
    print(f"Pair {idx}: '{inp}' -> '{outp}'")

    # Find minimal edit
    # Simple approach - look at differences
    if len(inp) != len(outp):
        # There's insertion/deletion
        if len(outp) > len(inp):
            # Insertion
            for i in range(len(inp)):
                if inp[i] != outp[i]:
                    print(f"  Insert '{outp[i]}' at position {i}")
                    break
            else:
                print(f"  Append '{outp[len(inp)]}' at end")
        else:
            # Deletion
            for i in range(len(outp)):
                if inp[i] != outp[i]:
                    print(f"  Delete '{inp[i]}' at position {i}")
                    break
            else:
                print(f"  Delete from position {len(outp)} onwards")
    else:
        # Same length - substitution
        for i in range(len(inp)):
            if inp[i] != outp[i]:
                print(f"  Change '{inp[i]}' to '{outp[i]}' at position {i}")
    print()

